  ["BY_SOURCE"] = { "発信元で", 0x46c54c7a, "." },
  ["BY_SOURCE_COMBATLOG_TOOLTIP"] = { "行の色を発信元で決めます。", 0x3e1cd603, "." },
  ["BY_TARGET"] = { "対象で", 0x4c1fd688, "." },
  ["BY_TARGET_COMBATLOG_TOOLTIP"] = { "行の色を対象で決めます。", 0x2aaf0ff6, "." },
  ["BroadcastText:316345"] = { "何千年もの間、", 0x86db738c, "." },
  ["BroadcastText:316346"] = { "ハイエルフの亡命者の一団が、安らかに", 0xe55ad36f, "." },
  ["BroadcastText:316348"] = { "空に浮かぶ聖域Zephras Isleに隠れ住んできた。", 0x4372a431, "." },
  ["BroadcastText:316349"] = { "自らを「Skyborne」と呼ぶ彼らは、", 0x8aa20a25, "." },
  ["BroadcastText:316350"] = { "大気のエレメンタルと絆で結ばれていた。", 0x55115e31, "." },
  ["BroadcastText:316351"] = { "Skywallの領域にいるそのエレメンタルが、彼らの島を空に浮かべていたのだ。", 0xddc29d35, "." },
  ["BroadcastText:316352"] = { "しかしここ数年、", 0xf7157c63, "." },
  ["BroadcastText:316353"] = { "エレメンタルは跡形もなく姿を消し、", 0xe44574f1, "." },
  ["BroadcastText:316354"] = { "雲間の安息の地で彼らを守っていた繊細な魔法が乱れてしまった。", 0x68b82607, "." },
  ["BroadcastText:316355"] = { "今、Skyborneのエルフの新たな世代は、かつてない変化の時を迎え、", 0x5277c225, "." },
  ["BroadcastText:316356"] = { "新たな味方と魔法の源を探し求めねばならない。", 0x72650d43, "." },
  ["BroadcastText:316358"] = { "隠された故郷を守り、未来を確かなものにするために……", 0xa97fa88e, "." },
  ["BroadcastText:329279"] = { "風変わりで、しばしば才気あふれるノームは、世界で最も奇妙な種族の一つとされている。", 0xdcebe743, "." },
  ["BroadcastText:329280"] = { "急進的な新技術の開発と、頭がくらくらするような驚異の工学の産物の建造に取りつかれた彼らが、生き延びて数を増やしてきたこと自体が驚きである。", 0xef45019c, "." },
  ["BroadcastText:329281"] = { "長年にわたり、ノームは独創的な兵器を生み出し、Hordeとの激しい戦いにおいてGrand Allianceを支えてきた。", 0xb517dde4, "." },
  ["BroadcastText:329282"] = { "驚異の技術都市Gnomereganで栄えるノームは、森に覆われたDun Moroghの峰々の資源を、いとこであるドワーフと分かち合っている。", 0x9cdefa76, "." },
})
